    private static Set<String> normalized(Collection<String> names){
        HashSet<String> out=new HashSet<>();
        for(String n:names)out.add(SopClassifier.norm(n));
        return out;
    }

    static boolean matches(String fileName,String group){
        Set<String> names=GROUPS.get(group);
        return names!=null&&names.contains(SopClassifier.norm(fileName));
    }

